def bubble_sort(lst):
    """冒泡排序算法实现"""
    for i in range(len(lst)):
        swapped = False
        for j in range(0, len(lst)-i-1):
            if lst[j] > lst[j+1]:
                lst[j], lst[j+1] = lst[j+1], lst[j]
                swapped = True
        if not swapped:
            break
    return lst
